pub fn parse_port(candidate: &str) -> i32 {
    let trimmed = candidate.trim_start_matches(char::is_whitespace);
    let (sign, digits_start) = match trimmed.as_bytes().first() {
        Some(b'+') => (1_i32, 1_usize),
        Some(b'-') => (-1_i32, 1_usize),
        _ => (1_i32, 0_usize),
    };

    let digit_count = trimmed[digits_start..]
        .bytes()
        .take_while(|byte| byte.is_ascii_digit())
        .count();

    if digit_count == 0 {
        return -1;
    }

    let mut value: u32 = 0;
    for byte in trimmed[digits_start..digits_start + digit_count].bytes() {
        value = value.saturating_mul(10).saturating_add(u32::from(byte - b'0'));
        if value > 65_535 {
            return -1;
        }
    }

    if sign < 0 {
        if value == 0 {
            return 0;
        }
        return -1;
    }

    value as i32
}

