use crate::port::parse_port;

pub struct URL {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
}

impl URL {
    pub fn new(input: &str) -> Self {
        let without_fragment = input.split_once('#').map_or(input, |(head, _)| head);
        let (base, query) = match without_fragment.split_once('?') {
            Some((head, tail)) => (head, tail.to_string()),
            None => (without_fragment, String::new()),
        };

        if let Some(scheme_end) = base.find("://") {
            let scheme = base[..scheme_end].to_string();
            let after_scheme = &base[scheme_end + 3..];
            let (authority, path) = match after_scheme.find('/') {
                Some(path_start) => (&after_scheme[..path_start], after_scheme[path_start..].to_string()),
                None => (after_scheme, String::new()),
            };

            let host_and_port = authority
                .split_once('@')
                .map_or(authority, |(_, tail)| tail);

            let (host, port) = match host_and_port.find(':') {
                Some(colon) => (
                    host_and_port[..colon].to_string(),
                    parse_port(&host_and_port[colon + 1..]),
                ),
                None => (host_and_port.to_string(), -1),
            };

            Self {
                scheme,
                host,
                port,
                path,
                query,
            }
        } else {
            Self {
                scheme: String::new(),
                host: String::new(),
                port: -1,
                path: base.to_string(),
                query,
            }
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }
}

#[cfg(test)]
mod tests {
    use super::URL;

    #[test]
    fn parses_basic_http_url() {
        let url = URL::new("http://example.com/path?x=1");

        assert_eq!(url.scheme(), "http");
        assert_eq!(url.host(), "example.com");
        assert_eq!(url.port(), -1);
        assert_eq!(url.path(), "/path");
        assert_eq!(url.query(), "x=1");
    }

    #[test]
    fn treats_non_authority_inputs_as_paths() {
        let url = URL::new("noscheme?x=1#frag");

        assert_eq!(url.scheme(), "");
        assert_eq!(url.host(), "");
        assert_eq!(url.port(), -1);
        assert_eq!(url.path(), "noscheme");
        assert_eq!(url.query(), "x=1");
    }

    #[test]
    fn parses_port_with_cpp_like_prefix_rules() {
        let url = URL::new("http://example.com:123abc/path");

        assert_eq!(url.host(), "example.com");
        assert_eq!(url.port(), 123);
        assert_eq!(url.path(), "/path");
    }

    #[test]
    fn rejects_ports_outside_the_valid_range() {
        let url = URL::new("http://example.com:65536/");

        assert_eq!(url.port(), -1);
        assert_eq!(url.path(), "/");
    }

    #[test]
    fn drops_userinfo_before_extracting_host() {
        let url = URL::new("http://user:pass@host:80/path");

        assert_eq!(url.host(), "host");
        assert_eq!(url.port(), 80);
        assert_eq!(url.path(), "/path");
    }

    #[test]
    fn ignores_scheme_markers_inside_the_query() {
        let url = URL::new("foo?bar://baz");

        assert_eq!(url.scheme(), "");
        assert_eq!(url.host(), "");
        assert_eq!(url.port(), -1);
        assert_eq!(url.path(), "foo");
        assert_eq!(url.query(), "bar://baz");
    }
}

